use std::fs; fn count() -> usize { fs::read_dir("/proc/self/task").unwrap().filter(|t| fs::read_to_string(t.as_ref().unwrap().path().join("comm")).map(|n| n.starts_with("probe-stall")).unwrap_or(false)).count() }
fn main() { let n: usize = std::env::args().nth(1).unwrap().parse().unwrap(); let mut seen = 0usize; let mut max_spins = 0u32; for _ in 0..n { let h = std::thread::Builder::new().name("probe-stall-report".into()).spawn(|| { let _ = 1 + 1; }).unwrap(); h.join().unwrap(); let c = count(); if c > 0 { seen += 1; let mut spins = 0u32; while count() > 0 { spins += 1; std::thread::yield_now(); } if spins > max_spins { max_spins = spins; } } } println!("iterations={n} leftover_after_join={seen} max_spins_until_gone={max_spins}"); }